def Polinomio_Coeficientes(X: list, Y:list):
    return BarycentricInterpolator(X,Y)

#punto 5.1
def integrar_trap(f: function, a:float, b:float, n: int): ## integro usando trapecios
    dx = (b-a)/n
    sum = f(a) + f(b)
    initial_a = a

    for i in range(n-1):
        a=a+dx
        sum += 2*f(a)

    sum = sum*dx/2

    ## seguí nomás la formula int f ~ dx/2 [f(a) + 2f(a+dx*i) + f(b)]

    print(f"Area (Trapecios) de la función es ~ {sum} | a={initial_a} | b={b} | n={n}")

    return sum

#punto 5.2
def integrar_simpson(f: function, a:float, b:float): ## integro usando trapecios

    ## seguí nomás la formula para simpson 1/3

    sum = ((b-a)/6)*(f(a) + 4*f((a+b)/2) + f(b))

    print(f"Area (Simpson 1/3) de la función es ~ {sum} | a={a} | b={b}")

    return sum

